import java.util.*;

class Solution {
    public String[] sortWords(String[] words) {
        Arrays.sort(words, (a, b) -> a.length() != b.length()
                ? Integer.compare(a.length(), b.length())
                : a.compareTo(b));
        return words;
    }
}

